7	module butterfly_general #(parameter layer = 5)(
8		input				clk,
9		input				rst,
10		input				data_in_start,
11		input				data_in_end,
12		input	[31:0]		A_real,
13		input	[31:0]		A_img,
14		output				next_level_start,
15		output	[31:0]		D_real,
16		output	[31:0]		D_img,
17		output				data_out_first,
18		output				data_out_last,
19		output				rotator_valid
20	);
21	
22	/*****************<-------		state machine		------->**************/
23		parameter			current_layer		= layer;
24		parameter			PERIOD				=	1<<layer;
25		parameter			HALT_FOR_NEXT_LAYER	=	6 + (PERIOD)/2;
26		parameter			STATE_IDLE			=	3'd0;
27		parameter			STATE_START			=	3'd1;
28		parameter			STATE_PROCESSING	=	3'd2;
29		parameter			STATE_END			=	3'd3;
30		reg		[2:0]		r_state				=	0;
31		reg					butterfly_enable	=	0;
32		reg					S					;
33		reg		[15:0]		S_counter			;
34		reg		[13:0]		next_level_start_counter=	 0;
35	
36		always@(posedge clk) begin
37			if(rst == 1)begin
38				r_state	<=	STATE_IDLE;
39			end else begin
40				case(r_state)
41					STATE_IDLE:begin
42						if(data_in_start == 1)begin
43							r_state	<=	STATE_START;
44						end else begin
45							r_state	<=	r_state;
46						end
47					end
48					STATE_START:begin
49						r_state	<=	STATE_PROCESSING;
50					end
51					STATE_PROCESSING:begin
52						if(data_in_end == 1)begin
53							r_state	<=	STATE_END;
54						end else begin
55							r_state	<=	r_state;
56						end
57					end
58					STATE_END:begin
59						r_state	<=	STATE_IDLE;
60					end
61					default:r_state = STATE_IDLE;
62				endcase
63			end
64		end
65	/*****************<-------		butterfly control	------->**************/
66	
67		always@(posedge clk) begin
68			if(rst == 1)begin
69				butterfly_enable	<=	0;
70			end else begin
71				if(r_state == STATE_START | r_state == STATE_PROCESSING | data_in_start == 1) begin
72					butterfly_enable	<=	1;
73				end else if (r_state== STATE_END) begin
74					butterfly_enable	<=	0;
75				end else begin
76					butterfly_enable	<=	butterfly_enable;
77				end
78			end
79		end
80		
81		always@(posedge clk) begin
82			if(rst == 1)begin
83				S_counter	<=	0;
84			end else begin
85				if(r_state == STATE_START | r_state == STATE_PROCESSING) begin
86					if(S_counter == PERIOD-1) begin
87						S_counter	<=	0;
88					end else begin
89						S_counter	<=	S_counter + 1;
90					end
91				end else begin
92					S_counter <= 0;
93				end
94			end
95		end
96	
97		always@(posedge clk) begin
98			if(rst == 1)begin
99				S	<=	1;
100			end else begin
101				if(data_in_start == 1) begin
102					S			<=	0;
103				end else if (S_counter == PERIOD/2-1 | S_counter == PERIOD-1)begin
104					S			<=	~S;
105				end else if (data_in_end == 1)begin
106					S			<=	1;
107				end else begin
108					S			<=	S;
109				end
110			end
111		end
112	
113	/*****************<-------		next layer control	------->**************/
114	
115		reg				r_next_level_start;
116		always@(posedge clk) begin
117			if(rst == 1)begin
118				r_next_level_start	<=	0;
119			end else begin
120				//if(next_level_start_counter == HALT_FOR_NEXT_LAYER-2) begin
121				//HALT_FOR_NEXT_LAYER-2 is used for anlogic version
122				//HALT_FOR_NEXT_LAYER-3 is used for vivado version
123				if(next_level_start_counter == HALT_FOR_NEXT_LAYER-3) begin
124					r_next_level_start	<=	1;
125				end else begin
126					r_next_level_start	<=	0;
127				end
128			end
129		end
130		
131		always@(posedge clk) begin
132			if(rst == 1)begin
133				next_level_start_counter	<=	0;
134			end else begin
135				if(r_state == STATE_START | r_state == STATE_PROCESSING)begin
136					if(next_level_start_counter == HALT_FOR_NEXT_LAYER)begin
137						next_level_start_counter <= next_level_start_counter;
138					end else begin
139						next_level_start_counter <= next_level_start_counter + 1;
140					end
141				end
142			end
143		end
144		assign next_level_start = r_next_level_start;
145	
146	
147	/*****************<-------rotator_valid------->**********************/
148		parameter				WAIT_FOR_ROTATOR = PERIOD - 2;
149		reg			[13:0]		r_count_rotator;
150		reg						r_rotator_valid;
151		reg						rotator_triger;
152	
153		always@(posedge clk) begin
154			if(rst == 1) begin
155				r_count_rotator		<=	0;
156			end else begin
157				if(r_state == STATE_START | r_state == STATE_PROCESSING)begin
158					if(r_count_rotator == WAIT_FOR_ROTATOR - 1)begin
159						r_count_rotator <= r_count_rotator;
160					end else begin
161						r_count_rotator <= r_count_rotator + 1;
162					end
163				end else begin
164					r_count_rotator <= 0;
165				end
166			end	
167		end
168	
169		always@(posedge clk)begin
170			if(rst == 1)begin
171				r_rotator_valid	<=	0;
172			end else begin
173				if(r_count_rotator == WAIT_FOR_ROTATOR - 1) begin
174					r_rotator_valid <= 1;
175				end else begin
176					r_rotator_valid <= 0;
177				end
178			end
179		end
180		assign rotator_valid = r_rotator_valid;
181	/*****************<-------		delay unit with ram	------->**************/
182	
183		reg		[32-1:0]	C_real;
184		reg		[32-1:0]	C_img;
185		wire	[32-1:0]	w_C_real;
186		wire	[32-1:0]	w_C_img;
187		wire	[32-1:0]	w_B_real;
188		wire	[32-1:0]	w_B_img;
189		wire	[32-1:0]	w_D_real_tmp;
190		wire	[32-1:0]	w_D_img_tmp;
191		wire				w_delay_out_first;
192		wire				w_delay_out_last;
193		reg					r_wea;
194		
195		always@(posedge clk) begin
196			if(rst) begin
197				r_wea <= 0;
198			end else begin
199				if(data_in_start | r_state == STATE_START | r_state == STATE_PROCESSING)begin
200					r_wea <= 1;
201				end else begin
202					r_wea <= 0;
203				end
204			end
205		end
