207	
208	delay #(.layer(current_layer))
209	delay(
210			.clk			(		clk				),
211			.rst			(		rst				),
212			.din_real		(		w_B_real		),
213			.din_img		(		w_B_img			),
214			.wea			(		r_wea			),
215			.dout_real		(		w_C_real		),
216			.dout_img		(		w_C_img			),
217			.out_first		(		w_delay_out_first		),
218			.out_last		(		w_delay_out_last		)
219		);
220	/*****************<-------		Butterfly			------->**************/
221	
222	butterfly butterfly(
223		.clk			(	clk),
224		.rst			(	rst),
